-- Riepilogo Ispettivo: stato fascicolo residuo (cloni delle righe 0061 e 5513)
INSERT INTO STATO_ESECUZIONE_PROCEDIMENTO (COD_TIPO_PROVVEDIMENTO, COD_MOTIVO, COD_STATO_PROCEDIMENTO, COD_STATO_FASCICOLO_RES, COD_POSIZIONE_GIURIDICA) -- 20261117-MEV_2026-105_SG
SELECT s.COD_TIPO_PROVVEDIMENTO, '0760', s.COD_STATO_PROCEDIMENTO, s.COD_STATO_FASCICOLO_RES, s.COD_POSIZIONE_GIURIDICA -- 20261117-MEV_2026-105_SG
  FROM STATO_ESECUZIONE_PROCEDIMENTO s WHERE s.COD_MOTIVO = '0061' -- 20261117-MEV_2026-105_SG
   AND NOT EXISTS (SELECT 1 FROM STATO_ESECUZIONE_PROCEDIMENTO x WHERE x.COD_MOTIVO = '0760');
INSERT INTO STATO_ESECUZIONE_PROCEDIMENTO (COD_TIPO_PROVVEDIMENTO, COD_MOTIVO, COD_STATO_PROCEDIMENTO, COD_STATO_FASCICOLO_RES, COD_POSIZIONE_GIURIDICA) -- 20261117-MEV_2026-105_SG
SELECT DISTINCT s.COD_TIPO_PROVVEDIMENTO, '0761', s.COD_STATO_PROCEDIMENTO, s.COD_STATO_FASCICOLO_RES, s.COD_POSIZIONE_GIURIDICA -- 20261117-MEV_2026-105_SG
  FROM STATO_ESECUZIONE_PROCEDIMENTO s WHERE s.COD_MOTIVO = '5513' -- 20261117-MEV_2026-105_SG
   AND NOT EXISTS (SELECT 1 FROM STATO_ESECUZIONE_PROCEDIMENTO x WHERE x.COD_MOTIVO = '0761');
-- 0762: come 5508 (nessuna riga in STATO_ESECUZIONE_PROCEDIMENTO), nessun inserimento.

